def Find_Max_Length(lst):
    max_length = 0
    current_length = 0
    for i in range(len(lst)):
        if i == 0 or lst[i] == lst[i-1]:
            current_length += 1
        else:
            max_length = max(max_length, current_length)
            current_length = 1
    return max(max_length, current_length)
```

