def zero_count(nums):
    zero_count = 0
    non_zero_count = 0
    for num in nums:
        if num == 0:
            zero_count += 1
        elif num != 0:
            non_zero_count += 1
    if non_zero_count == 0:
        return float('inf')
    return zero_count / non_zero_count
```

